nt_base_commit": "7ac44b4d1228134c44cf2de1accd39a5be8914da", "selected_parent_id": null, "reference": {"id": "3986de7ae7794f6e", "kind": "experiment", "role": "G", "tree_id": "e1:G-merge-1-1", "mission_id": "3986de7ae7794f6e", "facts": {"commit": "7ac44b4d1228134c44cf2de1accd39a5be8914da", "base_commit": "51265ff34ac5d85c12750a02b89d1a89d9a38e91", "parent_id": null, "source_ids": ["baseline-e1"], "source_count": 1}, "measured_outcome": {"status": "valid", "correct": true, "mean_seconds": 0.0010060664442416557, "score": 0.6482810353223648}, "diagnostic": "", "model_interpretation": {"claim": "Staging source positions and masses once per 256-thread CTA should reduce repeated global source loads across target threads while preserving the reference force arithmetic. This is an unmeasured candidate; controller correctness and timing results are required.", "transformations": "{"files":["src/nbody_kernel.cu"],"retained":["Stage source x, y, z, and mass in four 256-element shared-memory arrays, reusing each loaded source across a CTA.","Retain the target particle in registers and preserve the reference force expression, self-exclusion, update order, and exact mass copy.","Keep the existing 256-thread, 256-items-per-block launch configuration; handle incomplete source and target tiles without skipping block barriers."]}", "applicability": "", "next_experiment": "", "evidence_ids": []}, "source_available": true, "details_are_bounded": true}, "catalog": {"schema": "hpc-forest-memory-v1", "items": [{"role": "T1", "subject": "CTA shared-memory source tiling for one-thread-per-target work", "objective": "Develop a CTA source-tiled implementation focused on reusing each source particle across multiple target rows: cooperatively stage only the needed source fields in shared memory, synchronize safely, and handle incomplete source and target tiles. Initially keep the force arithmetic close to the reference to isolate the data-reuse change. Tune legal block, items_per_block, and shared_memory_bytes configurations. Respect grid.x=ceil(N/items_per_block): ensure every output row is written exactly once even when items_per_block differs from block. Preserve all required behavior, including self-exclusion, coincident positions, exact mass copying, and N=1. Report correctness and measured geometric-mean kernel time; do not change the harness or protocol.", "records": 1, "text_truncated": false}, {"role": "T2", "subject": "Warp-parallel source traversal with per-target partial reductions", "objective": "Explore a distinct warp-cooperative source-parallel mapping: lanes process different source particles for a target and combine partial force sums within the warp. Keep this line focused on parallelizing the source dimension rather than adding CTA shared-memory source tiling; assess the trade-off between shorter per-thread loops, reduction cost, and source traffic. Tune a legal block/items_per_block mapping that respects the fixed grid formula and writes each row exactly once, including tails and small N. Validate changed reduction order against the reference and independent FP64 oracle, all edge cases, and required tolerances; report measured geometric-mean kernel time.", "records": 1, "text_truncated": false}, {"role": "T3", "subject": "Inner-loop arithmetic and reciprocal-square-root optimization", "objective": "Explore instruction-level savings while retaining direct per-target source traversal: keep target state in registers, use explicit single-precision reciprocal-square-root where appropriate, and test the mathematically equivalent cancellation of the target-mass factor in acceleration. Treat the algebraic and approximate-math changes as hypotheses: preserve finite outputs, self-exclusion, update order, exact mass copying, and correctness for all specified inputs. Do not use global fast math or add shared-memory tiling or warp reductions in this line. Tune legal launch configuration while respecting the fixed grid formula and exact row coverage; report correctness and measured geometric-mean kernel time.", "records": 1, "text_truncated": false}], "offset": 0, "total": 3, "next_offset": null}, "last_read": {"schema": "hpc-forest-memory-v1", "id": "3986de7ae7794f6e", "commit": "7ac44b4d1228134c44cf2de1accd39a5be8914da", "snapshot_digest": "c04398b01a55e95f0a895ed8bf05903f3e84e56f852d89c5449e007ac37e12c3", "offset_unit": "characters", "path": "src/nbody_kernel.cu", "file_sha256": "72635a580101997f024941f95602161d1e00bb40331455a36e802cb59ff69a96", "total_characters": 2424, "text": "struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// The launch uses 256 threads and 256 target items per block.
// Each source tile is loaded once per CTA and reused by its target threads.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int tid = threadIdx.x;
    const int i = blockIdx.x * blockDim.x + tid;
    const bool active = i < n;

    Particle target{};
    if (active) {
        target = in[i];
    }

    __shared__ float tileX[256];
    __shared__ float tileY[256];
    __shared__ float tileZ[256];
    __shared__ float tileMass[256];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int tileStart = 0; tileStart < n; tileStart += 256) {
        const int sourceIndex = tileStart + tid;
        if (sourceIndex < n) {
            const Particle source = in[sourceIndex];
            tileX[tid] = source.x;
            tileY[tid] = source.y;
            tileZ[tid] = source.z;
            tileMass[tid] = source.mass;
        } else {
            tileX[tid] = 0.0f;
            tileY[tid] = 0.0f;
            tileZ[tid] = 0.0f;
            tileMass[tid] = 0.0f;
        }
        __syncthreads();

        if (active) {
            int tileCount = n - tileStart;
            if (tileCount > 256) {
                tileCount = 256;
            }
            for (int k = 0; k < tileCount; ++k) {
                const int j = tileStart + k;
                if (i == j) {
                    continue;
                }

                const float dx = tileX[k] - target.x;
                const float dy = tileY[k] - target.y;
                const float dz = tileZ[k] - target.z;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * target.mass * tileMass[k]) / (distSq * dist);
                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }
        __syncthreads();
    }

    if (active) {
        target.vx += (fx / target.mass) * dt;
        target.vy += (fy / target.mass) * dt;
        target.vz += (fz / target.mass) * dt;
        target.x += target.vx * dt;
        target.y += target.vy * dt;
        target.z += target.vz * dt;
        out[i] = target;
    }
}
